def find_components(grid):
    visited = set()
    components = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                if (r, c) in visited:
                    continue
                comp = {(r, c)}
                val = grid[r][c]
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if (nr, nc) not in visited and grid[nr][nc] == val:
                                visited.add((nr, nc))
                                comp.add((nr, nc))
                                queue.append((nr, nc))
                if comp and val != 2:  # exclude anchor
                    components.append((val, comp))
    return components

