    print(f"Color {val}: Input cols={sorted(demo1_in_cols[val])}, Output cols={sorted(demo1_out_cols.get(val, []))}")

# Fix the component finding - skip both 0 and anchor color 2
def get_components(grid, anchor_color=2):
    """Get connected components of each non-background, non-anchor color"""
    visited = set()
    h, w = len(grid), len(grid[0])
    components = []

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val == 0 or val == anchor_color:
                continue
            if (r, c) in visited:
                continue

            # BFS to find component
            comp = [(r, c)]
            queue = [(r, c)]

            while queue:
                cr, cc = queue.pop(0)
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == val and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            comp.append((nr, nc))
                            queue.append((nr, nc))

            if comp:
                components.append((val, comp))

    return components

